import os,json,subprocess,re,glob
R="/srv/projects/jellyfin-server"
d={"log_files":[],"service":{},"java":None}
for c,k in [(["systemctl","status","jellyfin-pink.service","--no-pager","-l"],"systemctl"),(["journalctl","-u","jellyfin-pink.service","-n","130","--no-pager","-o","cat"],"journal"),(["ldd",R+"/current/jellyfin"],"ldd")]:
 try:
  p=subprocess.run(c,capture_output=True,text=True,timeout=7)
  lines=(p.stdout+"\n"+p.stderr).splitlines()
  take=lines[-85:] if k=="journal" else lines[-50:]
  safe=[]
  for v in take:
   v=re.sub(r"https?://[^ ]+","[url]",v)
   v=re.sub(r"(?i)(password|token|secret)[=:][^ ,;]+",r"\1=[redacted]",v)
   safe.append(v[:440])
  d["service"][k]={"rc":p.returncode,"lines":safe}
 except Exception as e:d["service"][k]={"error":type(e).__name__}
for f in sorted(glob.glob(R+"/logs/*"))[-8:]:
 try:
  if not os.path.isfile(f):continue
  lines=open(f,encoding="utf8",errors="replace").read().splitlines()
  interesting=[x for x in lines if re.search(r"error|critical|fatal|exception|failed|start",x,re.I)][-35:]
  d["log_files"].append({"name":os.path.basename(f),"bytes":os.path.getsize(f),"error_lines":[re.sub(r"https?://[^ ]+","[url]",x[:430]) for x in interesting]})
 except Exception as e:d["log_files"].append({"name":os.path.basename(f),"error":type(e).__name__})
print(json.dumps(d,sort_keys=True))
